// brand, origin, model, dim(2D/3D), kind, MP, fps, sensor, interface, color, legacy, note, [supplierId]
const C = (b, o, m, d, k, mp, fps, s, i, col, _legacy, n, supId, specs = {}) => ({
  id: (b + m).replace(/\W/g, ''),
  brand: b,
  origin: o,
  model: m,
  dim: d,
  kind: k,
  mp,
  fps,
  sensor: s,
  iface: i,
  color: col,
  note: n || '',
  supplier: supId || null,
  resolution: specs.resolution || null,
  sensorSize: specs.sensorSize || null,
  shutter: specs.shutter || null,
  mount: specs.mount || null,
  cameraType: specs.type || null,
  image: b === 'Basler'
    ? (m.startsWith('blaze-') ? 'basler-blaze.svg' : 'basler-ace2.svg')
    : (b === 'KEYENCE' && m.startsWith('VJ-') ? 'keyence-vj.svg'
      : (BRAND_IMAGES[b] || 'basler.svg'))
});

